<?php $page_title='Detail Produk'; include 'partials/header.php';$id=(int)($_GET['id']??0);$st=$conn->prepare('SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=?');$st->bind_param('i',$id);$st->execute();$p=$st->get_result()->fetch_assoc();if(!$p){echo '<section class="container section">Produk tidak ditemukan.</section>';include 'partials/footer.php';exit;}$fp=final_price($p);$rv=$conn->prepare('SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.product_id=? ORDER BY r.id DESC');$rv->bind_param('i',$id);$rv->execute();$reviews=$rv->get_result(); ?>
<section class="section container"><div class="panel" style="display:grid;grid-template-columns:1fr 1fr;gap:35px"><div class="product-img" style="height:420px"><img src="assets/img/<?=htmlspecialchars($p['image'])?>"></div><div><small class="muted"><?=htmlspecialchars($p['category'])?></small><h1><?=htmlspecialchars($p['name'])?></h1><p class="muted" style="line-height:1.7"><?=nl2br(htmlspecialchars($p['description']))?></p><div class="price" style="font-size:30px"><?=rupiah($fp)?> <?php if($p['discount_percent']):?><span class="old-price"><?=rupiah($p['price'])?></span><?php endif;?></div><p>Stok tersedia: <b><?=$p['stock']?></b></p><div style="display:flex;gap:10px"><a class="btn" href="cart_add.php?id=<?=$p['id']?>">🛒 Tambah ke Keranjang</a><a class="btn ghost" href="wishlist_toggle.php?id=<?=$p['id']?>">♡ Wishlist</a></div></div></div></section>
<section class="section container"><div class="panel"><h2>Ulasan Pembeli</h2><?php if(is_logged_in()):?><form method="post" action="review_save.php" style="margin:15px 0"><input type="hidden" name="product_id" value="<?=$id?>"><div style="display:grid;grid-template-columns:160px 1fr auto;gap:8px"><select name="rating" required><?php for($i=5;$i>=1;$i--):?><option value="<?=$i?>"><?=$i?> bintang</option><?php endfor;?></select><input class="input" name="comment" placeholder="Tulis pengalamanmu"><button class="btn">Kirim</button></div></form><?php endif;?><?php if($reviews->num_rows===0):?><p class="muted">Belum ada ulasan.</p><?php endif;while($r=$reviews->fetch_assoc()):?><div class="review"><b><?=htmlspecialchars($r['name'])?></b> <span>⭐ <?=$r['rating']?>/5</span><p class="muted"><?=htmlspecialchars($r['comment'])?></p></div><?php endwhile;?></div></section><?php include 'partials/footer.php';?>
